// Omniflow batch 311-330 — PARTIAL COMPLETION PASS: sidebar fixes + language +
// identity stitching + auto-escalation + intent classifier + action requests.
// Run from the folder that contains BOTH repos (Omniflow/ and OmniFlow-Control-Plane/):
//   node add_batch_311_330.mjs
// SIDEBAR FIXES: all nine empty nav icons get real glyphs (Overview house, WhatsApp
// phone, Configure AI asterism, Conversations envelope, Customers smiley,
// Automations zap, Analytics bullseye, Business profile card, Knowledge base grid)
// and Settings gets the gear; BOTH sidebar containers (desktop aside + mobile
// drawer) become min-h-0 flex-1 overflow-y-auto so all 21 items scroll instead of
// hiding below the fold.
// CP: NEW portal_contacts.py — workspace reply language (auto/en/ur/roman) with
// GET/PUT, per-contact language GET/POST (auto deletes the row), a deterministic
// script/marker language detector (Arabic script -> ur, Roman-Urdu marker hits ->
// roman, else en), identity stitching (portal_contact_identities with a sorted
// deterministic identity_key, /contacts/link + /identities), and the autonomous
// ACTION REQUEST surface (portal_action_requests: cancel_order / change_address /
// refund_request created against a conversation, listed per contact/status,
// resolved done/declined — every step audited). portal_insights.py gains
// GET /insights/intent (ordered regex rules -> refund/order_status/complaint/
// pricing/delivery/greeting/other + entity extraction: phones, #order ids,
// emails). portal_growth.py record_kb_gap now returns the gap count via
// INSERT..RETURNING and auto-ESCALATES on the 2nd gap: probes portal_team_members
// (to_regclass-guarded), assigns the conversation to the first member, audits
// bot.escalated. connector_api.py calls maybe_detect_language on inbound (once per
// contact, ON CONFLICT DO NOTHING). customer_profile gains language,
// linked_channels and actions sections (all to_regclass-guarded).
// Web: portal.ts clients for all of the above + CustomerProfile gains
// language/linkedChannels/actions; EIGHT BFF routes (depth law: workspace 6,
// contacts/* 6, detect 7, insights/intent 6, conversations/[id]/actions 7,
// contacts/actions 6, contacts/actions/[id] 7); the 360 page shows a language
// chip, Linked: rows and an Action requests section; the Activity page gains an
// "Escalations" family chip (bot. prefix).
// Tests (rig, not this patcher): test_partial_completion.py 78,
// test_partial_completion_ui.py 51, test_customer_360.py extended to 33.
// Idempotent: re-run reports "already done" per block. Backups: *.pre_b311330.bak
import fs from "fs";
import { createRequire } from "module";
const require = createRequire(import.meta.url);

const BACKUP_TAG = ".pre_b311330.bak";
let applied = 0;
let already = 0;
let warnings = 0;

function compilePython(pathArg) {
  const { spawnSync } = require("child_process");
  for (const py of ["python3", "python", "py"]) {
    const probe = spawnSync(py, ["--version"], { encoding: "utf8" });
    if (probe.status !== 0) continue;
    const check = spawnSync(py, ["-c", "import sys;sys.exit(0 if sys.version_info[0]>=3 else 1)"], { encoding: "utf8" });
    if (check.status !== 0) continue;
    const result = spawnSync(py, ["-c", "import py_compile,sys;py_compile.compile(sys.argv[1],doraise=True);sys.exit(0)", pathArg], { encoding: "utf8" });
    return result.status === 0;
  }
  console.log("  (python not found — skipped compile guard)");
  return true;
}

function applySwaps(repoPath, marker, isCp, swaps) {
  if (!fs.existsSync(repoPath)) {
    console.log("SKIP (file not found): " + repoPath);
    warnings++;
    return;
  }
  const original = fs.readFileSync(repoPath, "utf8").replace(/\r\n/g, "\n");
  if (original.includes(marker)) {
    console.log("= " + repoPath + " (already patched)");
    already++;
    return;
  }
  const backup = repoPath + BACKUP_TAG;
  if (!fs.existsSync(backup)) fs.copyFileSync(repoPath, backup);
  let updated = original;
  let ok = true;
  let swapIndex = 0;
  for (const [frm, to] of swaps) {
    swapIndex++;
    if (!updated.includes(frm)) {
      const hits = original.split(frm.slice(0, 40)).length - 1;
      console.log(
        "  ? " + repoPath + " :: anchor NOT FOUND — report this" +
        " (swap " + swapIndex + "/" + swaps.length +
        ", anchor " + frm.length + " chars, starts: " +
        JSON.stringify(frm.slice(0, 60)) +
        ", " + hits + " partial hits)"
      );
      ok = false;
      warnings++;
      break;
    }
    updated = updated.replace(frm, to);
  }
  if (!ok) return;
  fs.writeFileSync(repoPath, updated, "utf8");
  if (isCp && !compilePython(repoPath)) {
    fs.copyFileSync(backup, repoPath);
    console.log("FAIL (compile failed, restored): " + repoPath);
    warnings++;
    return;
  }
  console.log("+ " + repoPath + " (" + swaps.length + ")");
  applied++;
}

function writeNew(repoPath, marker, isCp, content) {
  if (!fs.existsSync(repoPath)) {
    fs.mkdirSync(repoPath.replace(/\/[^/]*$/, ""), { recursive: true });
    fs.writeFileSync(repoPath, content, "utf8");
    if (isCp && !compilePython(repoPath)) {
      console.log("FAIL (compile failed): " + repoPath);
      warnings++;
      return;
    }
    console.log("+ " + repoPath + " (new file)");
    applied++;
    return;
  }
  const original = fs.readFileSync(repoPath, "utf8").replace(/\r\n/g, "\n");
  if (original.includes(marker)) {
    console.log("= " + repoPath + " (already patched)");
    already++;
    return;
  }
  console.log("  ? " + repoPath + " exists WITHOUT marker — report this");
  warnings++;
}




writeNew("OmniFlow-Control-Plane/portal_fraud.py", "portal_fraud", true,
"\"\"\"Fraud heuristics: deterministic risk scoring for COD and refund behaviour\n(no AI). Scores a contact from decline/refund history and keeps a flag row so\nmerchants can see risky buyers before confirming the next order.\"\"\"\n\nimport logging\nfrom typing import Any, Dict, List, Optional, Tuple\n\nfrom flask import Blueprint, jsonify, request\n\nfrom portal_auth import (\n    PortalAuthUnavailable,\n    authenticate_portal_request,\n)\nimport portal_db\n\nbp = Blueprint(\"portal_fraud\", __name__, url_prefix=\"/api/v1/portal\")\n\nlogger = logging.getLogger(__name__)\n\nFLAGS_TABLE = \"portal_fraud_flags\"\n\nLEVELS: Tuple[str, ...] = (\"clear\", \"watch\", \"high\")\nWATCH_THRESHOLD = 30\nHIGH_THRESHOLD = 60\nMAX_SCORE = 100\n\n_DECLINED_FIRST = 25\n_DECLINED_REPEAT = 45\n_REFUND_EACH = 15\n_REFUND_CAP = 2\n_NEW_CONTACT_BONUS = 10\n\n_FRAUD_DDL_READY = False\n\n\ndef _principal_or_error():\n    try:\n        principal = authenticate_portal_request()\n    except PortalAuthUnavailable as error:\n        return None, (jsonify({\"error\": {\"code\": \"portal_unavailable\",\n                                         \"message\": str(error)}}), 503)\n    if principal is None:\n        return None, (jsonify({\"error\": {\"code\": \"unauthorized\",\n                                         \"message\": \"Sign in required.\"}}), 401)\n    return principal, None\n\n\ndef _iso(value: Any) -> Optional[str]:\n    if value is None:\n        return None\n    try:\n        return value.isoformat()\n    except AttributeError:\n        return None\n\n\ndef _ensure_fraud_tables(conn) -> None:\n    global _FRAUD_DDL_READY\n    if _FRAUD_DDL_READY:\n        return\n    with conn.cursor() as cur:\n        cur.execute(\n            \"CREATE TABLE IF NOT EXISTS \" + portal_db._q(FLAGS_TABLE) +\n            \" (id BIGSERIAL PRIMARY KEY,\"\n            \" client_id BIGINT NOT NULL,\"\n            \" contact_id TEXT NOT NULL,\"\n            \" score INT NOT NULL DEFAULT 0,\"\n            \" level TEXT NOT NULL DEFAULT 'clear',\"\n            \" reasons TEXT NOT NULL DEFAULT '',\"\n            \" updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),\"\n            \" UNIQUE (client_id, contact_id))\"\n        )\n    conn.commit()\n    _FRAUD_DDL_READY = True\n\n\ndef _table_exists(cur, table: str) -> bool:\n    cur.execute(\"SELECT to_regclass(%s) AS found\", (table,))\n    rows = portal_db.rows(cur)\n    return bool(rows and rows[0].get(\"found\"))\n\n\ndef score_contact(cur, client_id, contact) -> Dict[str, Any]:\n    \"\"\"Deterministic score from COD declines, refund requests and account age.\n\n    Pure read pass (3 probes/counts) - safe to call inside any transaction.\n    \"\"\"\n    contact = str(contact or \"\").strip()[:100]\n    result: Dict[str, Any] = {\n        \"score\": 0,\n        \"level\": \"clear\",\n        \"reasons\": [],\n        \"declined\": 0,\n        \"refunds\": 0,\n        \"chats\": 0,\n    }\n    if not contact:\n        return result\n    declined = 0\n    if _table_exists(cur, \"portal_cod_requests\"):\n        cur.execute(\n            \"SELECT COUNT(*) AS total FROM \" + portal_db._q(\"portal_cod_requests\") +\n            \" WHERE client_id = %s AND contact_id = %s\"\n            \" AND status = 'declined'\",\n            (client_id, contact),\n        )\n        rows = portal_db.rows(cur)\n        declined = int((rows[0] if rows else {}).get(\"total\") or 0)\n    refunds = 0\n    if _table_exists(cur, \"portal_action_requests\"):\n        cur.execute(\n            \"SELECT COUNT(*) AS total FROM \" + portal_db._q(\"portal_action_requests\") +\n            \" WHERE client_id = %s AND contact_id = %s\"\n            \" AND kind = 'refund_request'\",\n            (client_id, contact),\n        )\n        rows = portal_db.rows(cur)\n        refunds = int((rows[0] if rows else {}).get(\"total\") or 0)\n    cur.execute(\n        \"SELECT COUNT(*) AS total FROM \" + portal_db._q(portal_db.CONV_TABLE) +\n        \" WHERE client_id = %s AND contact_id = %s\",\n        (client_id, contact),\n    )\n    rows = portal_db.rows(cur)\n    chats = int((rows[0] if rows else {}).get(\"total\") or 0)\n\n    score = 0\n    reasons: List[str] = []\n    if declined >= 2:\n        score += _DECLINED_REPEAT\n        reasons.append(\"Multiple COD orders declined\")\n    elif declined == 1:\n        score += _DECLINED_FIRST\n        reasons.append(\"One COD order declined\")\n    if refunds > 0:\n        score += _REFUND_EACH * min(refunds, _REFUND_CAP)\n        reasons.append(str(refunds) + \" refund request(s)\")\n    if chats <= 1 and (declined > 0 or refunds > 0):\n        score += _NEW_CONTACT_BONUS\n        reasons.append(\"New contact with order issues\")\n    score = min(score, MAX_SCORE)\n    level = \"clear\"\n    if score >= HIGH_THRESHOLD:\n        level = \"high\"\n    elif score >= WATCH_THRESHOLD:\n        level = \"watch\"\n    result.update({\n        \"score\": score,\n        \"level\": level,\n        \"reasons\": reasons,\n        \"declined\": declined,\n        \"refunds\": refunds,\n        \"chats\": chats,\n    })\n    return result\n\n\ndef _persist_flag(cur, client_id, contact, scored: Dict[str, Any]) -> None:\n    cur.execute(\n        \"INSERT INTO \" + portal_db._q(FLAGS_TABLE) +\n        \" (client_id, contact_id, score, level, reasons)\"\n        \" VALUES (%s, %s, %s, %s, %s)\"\n        \" ON CONFLICT (client_id, contact_id) DO UPDATE SET\"\n        \" score = EXCLUDED.score, level = EXCLUDED.level,\"\n        \" reasons = EXCLUDED.reasons, updated_at = NOW()\",\n        (client_id, contact, scored[\"score\"], scored[\"level\"],\n         \"; \".join(scored[\"reasons\"])[:300]),\n    )\n    portal_db.log_action(\n        cur,\n        client_id,\n        \"fraud.flagged\",\n        \"automation\",\n        None,\n        None,\n        (\"Risk \" + str(scored[\"level\"]) + \" (\" + str(scored[\"score\"]) +\n         \") for \" + contact)[:200],\n    )\n\n\n@bp.get(\"/fraud/score\")\ndef fraud_score():\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    contact = (request.args.get(\"contact\") or \"\").strip()[:100]\n    if not contact:\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": \"contact is required.\"}}), 400\n    client_id = principal[\"client_id\"]\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            _ensure_fraud_tables(conn)\n            with conn.cursor() as cur:\n                scored = score_contact(cur, client_id, contact)\n                if scored[\"level\"] != \"clear\":\n                    _persist_flag(cur, client_id, contact, scored)\n            conn.commit()\n        finally:\n            conn.close()\n    except Exception as error:\n        logger.warning(\"fraud score failed: %s\", error)\n        return jsonify(portal_db.portal_unavailable(error, \"fraud score\")[0]), 503\n    return jsonify(scored), 200\n\n\n@bp.get(\"/fraud/flags\")\ndef fraud_flags():\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            _ensure_fraud_tables(conn)\n            with conn.cursor() as cur:\n                cur.execute(\n                    \"SELECT contact_id, score, level, reasons, updated_at FROM \"\n                    + portal_db._q(FLAGS_TABLE) +\n                    \" WHERE client_id = %s AND score > 0\"\n                    \" ORDER BY updated_at DESC, contact_id ASC LIMIT 50\",\n                    (principal[\"client_id\"],),\n                )\n                rows = portal_db.rows(cur)\n        finally:\n            conn.close()\n    except Exception as error:\n        logger.warning(\"fraud flags read failed: %s\", error)\n        return jsonify(portal_db.portal_unavailable(error, \"fraud flags read\")[0]), 503\n    return jsonify({\"flags\": [\n        {\n            \"contact_id\": row.get(\"contact_id\"),\n            \"score\": int(row.get(\"score\") or 0),\n            \"level\": row.get(\"level\") or \"clear\",\n            \"reasons\": str(row.get(\"reasons\") or \"\"),\n            \"updated_at\": _iso(row.get(\"updated_at\")),\n        }\n        for row in rows\n    ]}), 200\n\n\ndef on_cod_declined(cur, client_id, contact) -> None:\n    \"\"\"Hook for the COD decline path: refresh the risk flag. Never raises.\"\"\"\n    contact = str(contact or \"\").strip()[:100]\n    if not contact:\n        return\n    try:\n        scored = score_contact(cur, client_id, contact)\n        if scored[\"level\"] != \"clear\":\n            _persist_flag(cur, client_id, contact, scored)\n    except Exception as error:\n        logger.warning(\"fraud decline hook failed: %s\", error)\n");


writeNew("OmniFlow-Control-Plane/portal_compliance.py", "portal_compliance", true,
"\"\"\"Compliance flags: STOP/opt-out handling and a merchant-managed opt-out\nlist. Outbound sends through the connector command queue never target an\nopted-out contact (guard lives in portal_growth._send_command).\"\"\"\n\nimport logging\nimport re\nfrom typing import Any, Optional\n\nfrom flask import Blueprint, jsonify, request\n\nfrom portal_auth import (\n    PortalAuthUnavailable,\n    authenticate_portal_request,\n    ensure_human_principal,\n)\nimport portal_db\n\nbp = Blueprint(\"portal_compliance\", __name__, url_prefix=\"/api/v1/portal\")\n\nlogger = logging.getLogger(__name__)\n\nOPTOUT_TABLE = \"portal_optouts\"\n\nREASONS = (\"customer\", \"merchant\")\n\n# Inbound STOP keywords (English + Roman Urdu), matched on word boundaries\n# anywhere in the message - a missed STOP is worse than a recoverable\n# false positive (the merchant can remove the opt-out).\nSTOP_RE = re.compile(\n    r\"\\b(stop|unsubscribe|band\\s+karo|band\\s+kar\\s+do|band\\s+kro|\"\n    r\"koi\\s+message\\s+nahi|no\\s+more\\s+messages?)\\b\",\n    re.I,\n)\n\n_COMPLIANCE_DDL_READY = False\n\n\ndef _principal_or_error():\n    try:\n        principal = authenticate_portal_request()\n    except PortalAuthUnavailable as error:\n        return None, (jsonify({\"error\": {\"code\": \"portal_unavailable\",\n                                         \"message\": str(error)}}), 503)\n    if principal is None:\n        return None, (jsonify({\"error\": {\"code\": \"unauthorized\",\n                                         \"message\": \"Sign in required.\"}}), 401)\n    return principal, None\n\n\ndef _iso(value: Any) -> Optional[str]:\n    if value is None:\n        return None\n    try:\n        return value.isoformat()\n    except AttributeError:\n        return None\n\n\ndef _ensure_compliance_tables(conn) -> None:\n    global _COMPLIANCE_DDL_READY\n    if _COMPLIANCE_DDL_READY:\n        return\n    with conn.cursor() as cur:\n        cur.execute(\n            \"CREATE TABLE IF NOT EXISTS \" + portal_db._q(OPTOUT_TABLE) +\n            \" (id BIGSERIAL PRIMARY KEY,\"\n            \" client_id BIGINT NOT NULL,\"\n            \" contact_id TEXT NOT NULL,\"\n            \" reason TEXT NOT NULL DEFAULT 'customer',\"\n            \" created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),\"\n            \" UNIQUE (client_id, contact_id))\"\n        )\n    conn.commit()\n    _COMPLIANCE_DDL_READY = True\n\n\n@bp.get(\"/compliance/optouts\")\ndef list_optouts():\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    query = (request.args.get(\"q\") or \"\").strip()[:100]\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            _ensure_compliance_tables(conn)\n            with conn.cursor() as cur:\n                sql = (\n                    \"SELECT contact_id, reason, created_at FROM \"\n                    + portal_db._q(OPTOUT_TABLE) +\n                    \" WHERE client_id = %s\"\n                )\n                params: list = [principal[\"client_id\"]]\n                if query:\n                    sql += \" AND contact_id ILIKE %s\"\n                    params.append(\"%\" + query + \"%\")\n                sql += \" ORDER BY created_at DESC, contact_id ASC LIMIT 100\"\n                cur.execute(sql, tuple(params))\n                rows = portal_db.rows(cur)\n        finally:\n            conn.close()\n    except Exception as error:\n        logger.warning(\"optouts read failed: %s\", error)\n        return jsonify(portal_db.portal_unavailable(error, \"optouts read\")[0]), 503\n    return jsonify({\"optouts\": [\n        {\n            \"contact_id\": row.get(\"contact_id\"),\n            \"reason\": row.get(\"reason\") or \"customer\",\n            \"created_at\": _iso(row.get(\"created_at\")),\n        }\n        for row in rows\n    ]}), 200\n\n\n@bp.post(\"/compliance/optouts\")\ndef add_optout():\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    forbidden = ensure_human_principal(principal)\n    if forbidden is not None:\n        return forbidden\n    payload = request.get_json(silent=True) or {}\n    contact = str(payload.get(\"contact\") or \"\").strip()[:100]\n    reason = payload.get(\"reason\") or \"customer\"\n    if not contact:\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": \"contact is required.\"}}), 400\n    if reason not in REASONS:\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": \"Pick customer or merchant.\"}}), 400\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            _ensure_compliance_tables(conn)\n            with conn.cursor() as cur:\n                cur.execute(\n                    \"INSERT INTO \" + portal_db._q(OPTOUT_TABLE) +\n                    \" (client_id, contact_id, reason) VALUES (%s, %s, %s)\"\n                    \" ON CONFLICT (client_id, contact_id)\"\n                    \" DO UPDATE SET reason = EXCLUDED.reason\",\n                    (principal[\"client_id\"], contact, reason),\n                )\n                portal_db.log_action(\n                    cur,\n                    principal[\"client_id\"],\n                    \"compliance.optout_manual\",\n                    \"customer_user\",\n                    principal.get(\"user_id\"),\n                    None,\n                    (\"Opt-out added for \" + contact + \" (\" + reason + \")\")[:200],\n                )\n            conn.commit()\n        finally:\n            conn.close()\n    except Exception as error:\n        logger.warning(\"optout save failed: %s\", error)\n        return jsonify(portal_db.portal_unavailable(error, \"optout save\")[0]), 503\n    return jsonify({\"ok\": True, \"contact_id\": contact, \"reason\": reason}), 200\n\n\n@bp.delete(\"/compliance/optouts\")\ndef remove_optout():\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    forbidden = ensure_human_principal(principal)\n    if forbidden is not None:\n        return forbidden\n    contact = (request.args.get(\"contact\") or \"\").strip()[:100]\n    if not contact:\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": \"contact is required.\"}}), 400\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            _ensure_compliance_tables(conn)\n            with conn.cursor() as cur:\n                cur.execute(\n                    \"DELETE FROM \" + portal_db._q(OPTOUT_TABLE) +\n                    \" WHERE client_id = %s AND contact_id = %s\"\n                    \" RETURNING contact_id\",\n                    (principal[\"client_id\"], contact),\n                )\n                removed = portal_db.rows(cur)\n                if not removed:\n                    return jsonify({\"error\": {\"code\": \"not_found\",\n                                              \"message\": \"Not in the opt-out\"\n                                                         \" list.\"}}), 404\n                portal_db.log_action(\n                    cur,\n                    principal[\"client_id\"],\n                    \"compliance.resubscribed\",\n                    \"customer_user\",\n                    principal.get(\"user_id\"),\n                    None,\n                    (\"Opt-out removed for \" + contact)[:200],\n                )\n            conn.commit()\n        finally:\n            conn.close()\n    except Exception as error:\n        logger.warning(\"optout delete failed: %s\", error)\n        return jsonify(portal_db.portal_unavailable(error, \"optout delete\")[0]), 503\n    return jsonify({\"ok\": True}), 200\n\n\ndef maybe_opt_out(client_id, contact, text, conn) -> None:\n    \"\"\"Ingest hook: record a STOP/opt-out request. Runs inside the ingest\n    transaction; never raises into the caller.\"\"\"\n    value = str(text or \"\").strip()\n    contact = str(contact or \"\").strip()[:100]\n    if not value or not contact:\n        return\n    if not STOP_RE.match(value[:200]):\n        return\n    with conn.cursor() as cur:\n        cur.execute(\n            \"INSERT INTO \" + portal_db._q(OPTOUT_TABLE) +\n            \" (client_id, contact_id, reason) VALUES (%s, %s, 'customer')\"\n            \" ON CONFLICT (client_id, contact_id) DO NOTHING\",\n            (client_id, contact),\n        )\n        portal_db.log_action(\n            cur,\n            client_id,\n            \"compliance.optout\",\n            \"customer\",\n            None,\n            None,\n            (\"Customer asked to stop: \" + contact)[:200],\n        )\n");


