writeNew("Omniflow/app/api/omniflow/portal/compliance/optouts/route.ts", "listOptOuts", false,
"import {\n  addOptOut,\n  listOptOuts,\n  removeOptOut,\n  requirePortalAccessToken,\n} from \"../../../../../../lib/omniflow/portal\";\nimport {\n  noStoreHeaders,\n  safeJson,\n} from \"../../../../../../lib/omniflow/request-security\";\nimport { ControlPlaneRequestError } from \"../../../../../../lib/omniflow/control-plane\";\n\n\nexport async function GET(request: Request) {\n  const accessToken = await requirePortalAccessToken();\n  if (!accessToken) {\n    return safeJson(\n      { error: { code: \"unauthorized\", message: \"Sign in required.\" } },\n      401\n    );\n  }\n\n  const params = new URL(request.url).searchParams;\n  const query = (params.get(\"q\") || \"\").trim();\n  if (query.length > 100) {\n    return safeJson(\n      { error: { code: \"bad_request\", message: \"q is too long.\" } },\n      400\n    );\n  }\n\n  try {\n    const optouts = await listOptOuts(accessToken, query);\n    if (optouts === null) {\n      return safeJson(\n        { error: { code: \"portal_unavailable\", message: \"Try again shortly.\" } },\n        503\n      );\n    }\n    return safeJson({ optouts }, 200);\n  } catch (error) {\n    if (error instanceof ControlPlaneRequestError && error.isUnauthorized) {\n      return safeJson(\n        { error: { code: \"unauthorized\", message: \"Session expired.\" } },\n        401\n      );\n    }\n    return safeJson(\n      { error: { code: \"portal_unavailable\", message: \"Try again shortly.\" } },\n      503\n    );\n  }\n}\n\n\nexport async function POST(request: Request) {\n  const accessToken = await requirePortalAccessToken();\n  if (!accessToken) {\n    return safeJson(\n      { error: { code: \"unauthorized\", message: \"Sign in required.\" } },\n      401\n    );\n  }\n\n  const payload: unknown = await request.json().catch(() => null);\n  const body =\n    payload !== null && typeof payload === \"object\"\n      ? (payload as Record<string, unknown>)\n      : {};\n  const contact = String(body.contact || \"\").trim();\n  const reason = String(body.reason || \"customer\");\n  if (!contact || contact.length > 100) {\n    return safeJson(\n      { error: { code: \"bad_request\", message: \"contact is required.\" } },\n      400\n    );\n  }\n  if (![\"customer\", \"merchant\"].includes(reason)) {\n    return safeJson(\n      { error: { code: \"bad_request\", message: \"Pick customer or merchant.\" } },\n      400\n    );\n  }\n\n  try {\n    const saved = await addOptOut(accessToken, contact, reason);\n    if (saved === null) {\n      return safeJson(\n        { error: { code: \"portal_unavailable\", message: \"Try again shortly.\" } },\n        503\n      );\n    }\n    return safeJson(saved, 200);\n  } catch (error) {\n    if (error instanceof ControlPlaneRequestError && error.isUnauthorized) {\n      return safeJson(\n        { error: { code: \"unauthorized\", message: \"Session expired.\" } },\n        401\n      );\n    }\n    return safeJson(\n      { error: { code: \"portal_unavailable\", message: \"Try again shortly.\" } },\n      503\n    );\n  }\n}\n\n\nexport async function DELETE(request: Request) {\n  const accessToken = await requirePortalAccessToken();\n  if (!accessToken) {\n    return safeJson(\n      { error: { code: \"unauthorized\", message: \"Sign in required.\" } },\n      401\n    );\n  }\n\n  const params = new URL(request.url).searchParams;\n  const contact = (params.get(\"contact\") || \"\").trim();\n  if (!contact || contact.length > 100) {\n    return safeJson(\n      { error: { code: \"bad_request\", message: \"contact is required.\" } },\n      400\n    );\n  }\n\n  try {\n    const removed = await removeOptOut(accessToken, contact);\n    if (removed === null) {\n      return safeJson(\n        { error: { code: \"portal_unavailable\", message: \"Try again shortly.\" } },\n        503\n      );\n    }\n    if (removed === \"not_found\") {\n      return safeJson(\n        { error: { code: \"not_found\", message: \"Not in the opt-out list.\" } },\n        404\n      );\n    }\n    return safeJson({ ok: true }, 200);\n  } catch (error) {\n    if (error instanceof ControlPlaneRequestError && error.isUnauthorized) {\n      return safeJson(\n        { error: { code: \"unauthorized\", message: \"Session expired.\" } },\n        401\n      );\n    }\n    return safeJson(\n      { error: { code: \"portal_unavailable\", message: \"Try again shortly.\" } },\n      503\n    );\n  }\n}\n");


writeNew("Omniflow/app/api/omniflow/portal/conversations/[id]/assist/route.ts", "getConversationAssist", false,
"import {\n  getConversationAssist,\n  requirePortalAccessToken,\n} from \"../../../../../../../lib/omniflow/portal\";\nimport {\n  noStoreHeaders,\n  safeJson,\n} from \"../../../../../../../lib/omniflow/request-security\";\nimport { ControlPlaneRequestError } from \"../../../../../../../lib/omniflow/control-plane\";\n\n\nexport async function GET(\n  _request: Request,\n  { params }: { params: Promise<{ id: string }> }\n) {\n  const accessToken = await requirePortalAccessToken();\n  if (!accessToken) {\n    return safeJson(\n      { error: { code: \"unauthorized\", message: \"Sign in required.\" } },\n      401\n    );\n  }\n\n  const { id } = await params;\n  const conversationId = Number.parseInt(id, 10);\n  if (!Number.isFinite(conversationId) || conversationId <= 0) {\n    return safeJson(\n      { error: { code: \"bad_request\", message: \"id must be a number.\" } },\n      400\n    );\n  }\n\n  try {\n    const assist = await getConversationAssist(accessToken, conversationId);\n    if (assist === null) {\n      return safeJson(\n        { error: { code: \"not_found\", message: \"Conversation not found.\" } },\n        404\n      );\n    }\n    return safeJson(assist, 200);\n  } catch (error) {\n    if (error instanceof ControlPlaneRequestError && error.isUnauthorized) {\n      return safeJson(\n        { error: { code: \"unauthorized\", message: \"Session expired.\" } },\n        401\n      );\n    }\n    return safeJson(\n      { error: { code: \"portal_unavailable\", message: \"Try again shortly.\" } },\n      503\n    );\n  }\n}\n");


writeNew("Omniflow/app/dashboard/(portal)/compliance/page.tsx", "Add an opt-out", false,
"\"use client\";\n\nimport { useCallback, useEffect, useState } from \"react\";\n\ninterface OptOutRow {\n  contactId: string;\n  reason: string;\n  createdAt: string | null;\n}\n\n\nexport default function CompliancePage() {\n  const [rows, setRows] = useState<OptOutRow[]>([]);\n  const [query, setQuery] = useState(\"\");\n  const [contact, setContact] = useState(\"\");\n  const [reason, setReason] = useState(\"customer\");\n  const [loading, setLoading] = useState(true);\n  const [busy, setBusy] = useState(false);\n  const [note, setNote] = useState(\"\");\n  const [failed, setFailed] = useState(false);\n\n  const load = useCallback(async (q: string) => {\n    setLoading(true);\n    try {\n      const response = await fetch(\n        \"/api/omniflow/portal/compliance/optouts?q=\" + encodeURIComponent(q),\n        { cache: \"no-store\" }\n      );\n      if (!response.ok) {\n        setFailed(true);\n        setRows([]);\n        return;\n      }\n      const payload: unknown = await response.json().catch(() => null);\n      const raw =\n        payload !== null && typeof payload === \"object\"\n          ? (payload as Record<string, unknown>).optouts\n          : null;\n      setFailed(false);\n      setRows(Array.isArray(raw) ? (raw as OptOutRow[]) : []);\n    } catch {\n      setFailed(true);\n      setRows([]);\n    } finally {\n      setLoading(false);\n    }\n  }, []);\n\n  useEffect(() => {\n    void load(\"\");\n  }, [load]);\n\n  async function addOptOut() {\n    const trimmed = contact.trim();\n    if (!trimmed || busy) return;\n    setBusy(true);\n    setNote(\"\");\n    try {\n      const response = await fetch(\n        \"/api/omniflow/portal/compliance/optouts\",\n        {\n          method: \"POST\",\n          headers: { \"Content-Type\": \"application/json\" },\n          body: JSON.stringify({ contact: trimmed, reason }),\n        }\n      );\n      if (response.ok) {\n        setContact(\"\");\n        setNote(\"Added to the opt-out list. They will not receive automated sends.\");\n        await load(query);\n      } else {\n        setNote(\"Could not add the contact. Check the number and try again.\");\n      }\n    } catch {\n      setNote(\"Could not add the contact. Try again shortly.\");\n    } finally {\n      setBusy(false);\n    }\n  }\n\n  async function removeOptOut(row: OptOutRow) {\n    if (busy) return;\n    setBusy(true);\n    setNote(\"\");\n    try {\n      const response = await fetch(\n        \"/api/omniflow/portal/compliance/optouts?contact=\" +\n          encodeURIComponent(row.contactId),\n        { method: \"DELETE\" }\n      );\n      if (response.ok) {\n        setNote(\"Removed. The contact can receive messages again.\");\n        await load(query);\n      } else {\n        setNote(\"Could not remove the contact. Try again shortly.\");\n      }\n    } catch {\n      setNote(\"Could not remove the contact. Try again shortly.\");\n    } finally {\n      setBusy(false);\n    }\n  }\n\n  return (\n    <div className=\"mx-auto max-w-3xl 2xl:max-w-5xl\">\n      <div className=\"mb-6\">\n        <h1 className=\"text-2xl font-semibold tracking-tight text-white\">\n          Compliance\n        </h1>\n        <p className=\"mt-1 text-sm text-slate-500\">\n          Customers who asked to stop receiving messages. Automated sends to\n          these contacts are blocked at the source.\n        </p>\n      </div>\n\n      <section className=\"rounded-2xl border border-white/[0.07] bg-white/[0.02] p-4\">\n        <p className=\"text-xs font-semibold text-white\">Add an opt-out</p>\n        <div className=\"mt-3 flex flex-col gap-2 sm:flex-row\">\n          <input\n            value={contact}\n            onChange={(event) => setContact(event.target.value)}\n            placeholder=\"923001234567\"\n            className=\"flex-1 rounded-xl border border-white/[0.07] bg-white/[0.02] px-3 py-2 text-sm text-white placeholder-slate-600 outline-none transition-colors focus:border-cyan-400/40\"\n          />\n          <select\n            value={reason}\n            onChange={(event) => setReason(event.target.value)}\n            className=\"rounded-xl border border-white/[0.07] bg-white/[0.02] px-3 py-2 text-sm text-white outline-none focus:border-cyan-400/40\"\n          >\n            <option value=\"customer\">Customer asked</option>\n            <option value=\"merchant\">Merchant decision</option>\n          </select>\n          <button\n            onClick={() => void addOptOut()}\n            disabled={busy || !contact.trim()}\n            className=\"rounded-xl border border-cyan-400/25 bg-cyan-400/[0.08] px-4 py-2 text-sm font-medium text-cyan-300 transition-colors hover:bg-cyan-400/[0.14] disabled:cursor-not-allowed disabled:opacity-50\"\n          >\n            Add\n          </button>\n        </div>\n        {note ? <p className=\"mt-2 text-xs text-slate-400\">{note}</p> : null}\n      </section>\n\n      <section className=\"mt-4 rounded-2xl border border-white/[0.07] bg-white/[0.02] p-4\">\n        <div className=\"flex flex-col gap-2 sm:flex-row sm:items-center sm:justify-between\">\n          <p className=\"text-xs font-semibold text-white\">Opt-out list</p>\n          <div className=\"flex items-center gap-2\">\n            <input\n              value={query}\n              onChange={(event) => setQuery(event.target.value)}\n              placeholder=\"Search number\"\n              className=\"w-full rounded-xl border border-white/[0.07] bg-white/[0.02] px-3 py-1.5 text-sm text-white placeholder-slate-600 outline-none transition-colors focus:border-cyan-400/40 sm:w-48\"\n            />\n            <button\n              onClick={() => void load(query)}\n              className=\"shrink-0 rounded-xl border border-white/[0.08] bg-white/[0.02] px-3 py-1.5 text-xs font-medium text-slate-300 transition-colors hover:bg-white/[0.05]\"\n            >\n              Search\n            </button>\n          </div>\n        </div>\n\n        {loading ? (\n          <div className=\"mt-3 animate-pulse space-y-2\">\n            <div className=\"h-9 rounded-xl bg-white/[0.03]\" />\n            <div className=\"h-9 rounded-xl bg-white/[0.03]\" />\n          </div>\n        ) : failed ? (\n          <p className=\"mt-3 text-xs text-slate-500\">\n            The opt-out list is temporarily unavailable. Try again shortly.\n          </p>\n        ) : rows.length === 0 ? (\n          <p className=\"mt-3 text-xs text-slate-500\">\n            {query\n              ? \"No opt-outs match this search.\"\n              : \"No opt-outs yet. When a customer sends STOP, they appear here automatically.\"}\n          </p>\n        ) : (\n          <ul className=\"mt-3 space-y-1.5\">\n            {rows.map((row) => (\n              <li\n                key={row.contactId}\n                className=\"flex flex-col gap-2 rounded-xl border border-white/[0.06] bg-white/[0.015] px-3 py-2 sm:flex-row sm:items-center sm:justify-between\"\n              >\n                <div className=\"min-w-0\">\n                  <p className=\"truncate text-sm text-slate-200\">{row.contactId}</p>\n                  <p className=\"text-[10px] uppercase tracking-wider text-slate-500\">\n                    {row.reason === \"merchant\" ? \"Merchant decision\" : \"Customer asked\"}\n                  </p>\n                </div>\n                <button\n                  onClick={() => void removeOptOut(row)}\n                  disabled={busy}\n                  className=\"shrink-0 rounded-lg border border-white/[0.08] bg-white/[0.02] px-3 py-1 text-xs text-slate-300 transition-colors hover:bg-white/[0.06] disabled:cursor-not-allowed disabled:opacity-50\"\n                >\n                  Remove\n                </button>\n              </li>\n            ))}\n          </ul>\n        )}\n      </section>\n    </div>\n  );\n}\n");


writeNew("Omniflow/app/dashboard/(portal)/conversations/[id]/AssistCard.tsx", "Agent assist", false,
"\"use client\";\n\nimport { useCallback, useEffect, useState } from \"react\";\nimport {\n  getConversationAssist,\n  requirePortalAccessToken,\n  type AssistResult,\n} from \"../../../../../lib/omniflow/portal\";\n\n\nexport default function AssistCard({ conversationId }: { conversationId: number }) {\n  const [assist, setAssist] = useState<AssistResult | null>(null);\n  const [busy, setBusy] = useState(false);\n\n  const load = useCallback(async () => {\n    if (!Number.isFinite(conversationId) || conversationId <= 0) return;\n    setBusy(true);\n    try {\n      const accessToken = await requirePortalAccessToken();\n      if (!accessToken) return;\n      const result = await getConversationAssist(accessToken, conversationId);\n      if (result !== null) setAssist(result);\n    } catch {\n      return;\n    } finally {\n      setBusy(false);\n    }\n  }, [conversationId]);\n\n  useEffect(() => {\n    void load();\n  }, [load]);\n\n  if (!assist) return null;\n  const empty =\n    assist.suggestions.length === 0 &&\n    assist.intent === \"other\" &&\n    assist.linked.length === 0 &&\n    !assist.language;\n  if (empty) return null;\n\n  return (\n    <section className=\"of-fade-up rounded-2xl border border-white/[0.07] bg-white/[0.02] p-4\">\n      <div className=\"flex items-center justify-between gap-2\">\n        <p className=\"text-xs font-semibold text-white\">Agent assist</p>\n        <button\n          onClick={() => void load()}\n          disabled={busy}\n          className=\"rounded-lg border border-white/[0.08] bg-white/[0.02] px-2.5 py-1 text-[11px] text-slate-300 transition-colors hover:bg-white/[0.06] disabled:cursor-not-allowed disabled:opacity-50\"\n        >\n          {busy ? \"Checking\u2026\" : \"Refresh\"}\n        </button>\n      </div>\n\n      <div className=\"mt-2 flex flex-wrap items-center gap-1.5 text-[10px]\">\n        <span className=\"rounded-md border border-cyan-400/25 bg-cyan-400/[0.08] px-1.5 py-0.5 text-cyan-300\">\n          Intent: {assist.intent}\n        </span>\n        {assist.language ? (\n          <span className=\"rounded-md border border-violet-400/25 bg-violet-400/[0.08] px-1.5 py-0.5 text-violet-300\">\n            Language: {assist.language}\n          </span>\n        ) : null}\n        {assist.linked.map((linked) => (\n          <span\n            key={linked}\n            className=\"rounded-md border border-white/[0.08] bg-white/[0.02] px-1.5 py-0.5 text-slate-400\"\n          >\n            Linked: {linked}\n          </span>\n        ))}\n      </div>\n\n      {assist.suggestions.length > 0 ? (\n        <ul className=\"mt-3 space-y-2\">\n          {assist.suggestions.map((suggestion) => (\n            <li\n              key={suggestion.id}\n              className=\"rounded-xl border border-white/[0.06] bg-white/[0.015] px-3 py-2\"\n            >\n              <p className=\"text-xs font-medium text-slate-200\">\n                {suggestion.question}\n              </p>\n              <p className=\"mt-1 text-xs text-slate-400\">{suggestion.snippet}</p>\n              {suggestion.matched.length > 0 ? (\n                <p className=\"mt-1 text-[10px] text-slate-600\">\n                  Matched: {suggestion.matched.join(\", \")}\n                </p>\n              ) : null}\n            </li>\n          ))}\n        </ul>\n      ) : (\n        <p className=\"mt-2 text-xs text-slate-500\">\n          No knowledge-base matches for the latest messages.\n        </p>\n      )}\n    </section>\n  );\n}\n");


writeNew("Omniflow/connector-node/telegram_bridge.py", "INGEST_PATH", false,
"\"\"\"OmniFlow Telegram bridge (v0) - runs on the connector laptop.\n\nCopies to the laptop next to the WhatsApp connector. Zero dependencies\n(stdlib only). Bridges a Telegram bot to the SAME Control Plane the WhatsApp\nconnector uses:\n\n  - Inbound: Telegram getUpdates (long poll) -> POST /connector/whatsapp/messages\n    with channel=\"telegram\" and contacts addressed as \"tg:<chat_id>\".\n  - Outbound: polls /connector/whatsapp/commands?channel=telegram every\n    POLL_SECONDS and delivers send_message commands addressed to \"tg:*\"\n    contacts via sendMessage. WhatsApp-addressed commands are left untouched\n    (the WhatsApp bridge keeps polling WITHOUT the channel filter).\n\nEnv:\n  OMNIFLOW_CP_URL       https://<your-control-plane>   (no trailing slash)\n  OMNIFLOW_SERVICE_KEY  the connector service key\n  TELEGRAM_BOT_TOKEN    from @BotFather\n  OMNIFLOW_CLIENT_ID    optional explicit tenant id (omit to use the default)\n  OMNIFLOW_POLL_SECONDS command poll interval (default 15)\n\nRun:  python3 telegram_bridge.py\n\"\"\"\n\nimport json\nimport os\nimport time\nimport urllib.parse\nimport urllib.request\n\nCP_URL = os.environ.get(\"OMNIFLOW_CP_URL\", \"\").rstrip(\"/\")\nSERVICE_KEY = os.environ.get(\"OMNIFLOW_SERVICE_KEY\", \"\")\nBOT_TOKEN = os.environ.get(\"TELEGRAM_BOT_TOKEN\", \"\")\nCLIENT_ID = os.environ.get(\"OMNIFLOW_CLIENT_ID\", \"\")\nPOLL_SECONDS = float(os.environ.get(\"OMNIFLOW_POLL_SECONDS\", \"15\"))\nTG_TIMEOUT = 55\nAPI_TIMEOUT = 20\n\nINGEST_PATH = \"/api/v1/connector/whatsapp/messages\"\nCOMMANDS_PATH = \"/api/v1/connector/whatsapp/commands\"\nACK_PATH = \"/api/v1/connector/whatsapp/commands/ack\"\nTG_API = \"https://api.telegram.org/bot\" + BOT_TOKEN + \"/\"\n\n\ndef _http_json(url, payload=None, timeout=API_TIMEOUT):\n    \"\"\"POST payload (or GET when payload is None); returns parsed JSON.\"\"\"\n    data = None\n    headers = {}\n    if payload is not None:\n        data = json.dumps(payload).encode(\"utf-8\")\n        headers[\"Content-Type\"] = \"application/json\"\n    if SERVICE_KEY:\n        headers[\"X-Omniflow-Key\"] = SERVICE_KEY\n    request = urllib.request.Request(url, data=data, headers=headers)\n    with urllib.request.urlopen(request, timeout=timeout) as response:\n        body = response.read().decode(\"utf-8\", \"replace\")\n    return json.loads(body) if body else {}\n\n\ndef tg_api(method, params=None, timeout=TG_TIMEOUT):\n    \"\"\"Call a Telegram Bot API method (params go in the query string).\"\"\"\n    query = \"\"\n    if params:\n        query = \"?\" + urllib.parse.urlencode(params)\n    return _http_json(TG_API + method + query, None, timeout=timeout)\n\n\ndef map_update(update):\n    \"\"\"Telegram update -> CP ingest item, or None when not a text message.\"\"\"\n    message = (update or {}).get(\"message\") or {}\n    chat = message.get(\"chat\") or {}\n    sender = message.get(\"from\") or {}\n    text = message.get(\"text\") or message.get(\"caption\") or \"\"\n    chat_id = chat.get(\"id\")\n    if chat_id is None or not str(text).strip():\n        return None\n    name = \" \".join(\n        part for part in (sender.get(\"first_name\"), sender.get(\"last_name\"))\n        if isinstance(part, str) and part.strip()\n    ).strip() or (chat.get(\"title\") if isinstance(chat.get(\"title\"), str) else \"\")\n    return {\n        \"from\": \"tg:\" + str(chat_id),\n        \"body\": str(text)[:1000],\n        \"name\": name or None,\n        \"direction\": \"in\",\n        \"channel\": \"telegram\",\n    }\n\n\ndef extract_out(command):\n    \"\"\"send_message command -> (tg_chat_id, body) or None for other channels.\"\"\"\n    payload = (command or {}).get(\"payload\") or {}\n    to = str(payload.get(\"external_user_id\") or \"\")\n    if not to.startswith(\"tg:\"):\n        return None\n    chat_id = to[3:]\n    if not chat_id.lstrip(\"-\").isdigit():\n        return None\n    return chat_id, str(payload.get(\"body\") or \"\")[:4000]\n\n\ndef ingest_messages(items):\n    payload = {\"messages\": items}\n    if CLIENT_ID:\n        payload[\"client_id\"] = int(CLIENT_ID)\n    return _http_json(CP_URL + INGEST_PATH, payload)\n\n\ndef poll_commands():\n    path = COMMANDS_PATH + \"?limit=20&channel=telegram\"\n    if CLIENT_ID:\n        path += \"&client_id=\" + urllib.parse.quote(CLIENT_ID)\n    return _http_json(CP_URL + path, None, timeout=API_TIMEOUT)\n\n\ndef ack_command(command_id, ok, note=\"\"):\n    payload = {\"command_id\": int(command_id), \"ok\": bool(ok)}\n    if note:\n        payload[\"note\"] = str(note)[:300]\n    if CLIENT_ID:\n        payload[\"client_id\"] = int(CLIENT_ID)\n    return _http_json(CP_URL + ACK_PATH, payload)\n\n\ndef run_forever():\n    if not (CP_URL and SERVICE_KEY and BOT_TOKEN):\n        raise SystemExit(\n            \"Set OMNIFLOW_CP_URL, OMNIFLOW_SERVICE_KEY and TELEGRAM_BOT_TOKEN.\"\n        )\n    print(\"OmniFlow Telegram bridge started.\")\n    offset = 0\n    while True:\n        try:\n            result = tg_api(\n                \"getUpdates\",\n                {\"offset\": offset, \"timeout\": TG_TIMEOUT - 5, \"limit\": 20},\n            )\n            for update in result.get(\"result\") or []:\n                offset = max(offset, int(update.get(\"update_id\") or 0) + 1)\n                item = map_update(update)\n                if item:\n                    ingest_messages([item])\n        except Exception as error:  # keep the bridge alive on any transient error\n            print(\"ingest loop error:\", error)\n            time.sleep(3)\n        try:\n            batch = poll_commands()\n            for command in batch.get(\"commands\") or []:\n                out = extract_out(command)\n                if out is None:\n                    continue\n                chat_id, body = out\n                try:\n                    tg_api(\n                        \"sendMessage\",\n                        {\"chat_id\": chat_id, \"text\": body},\n                        timeout=API_TIMEOUT,\n                    )\n                    ack_command(command.get(\"id\"), True)\n                except Exception as send_error:\n                    ack_command(command.get(\"id\"), False, str(send_error))\n        except Exception as error:\n            print(\"command loop error:\", error)\n        time.sleep(POLL_SECONDS)\n\n\nif __name__ == \"__main__\":\n    run_forever()\n");


writeNew("Omniflow/connector-node/README.md", "Telegram bridge", false,
"# Connector node (laptop-side bridges)\n\nThese scripts run on the merchant's laptop next to the WhatsApp connector.\nThey are NOT part of the deployed website; copy them manually.\n\n## Telegram bridge (v0)\n\nBridges a Telegram bot to OmniFlow through the SAME Control Plane endpoints\nthe WhatsApp connector already uses, with `channel=\"telegram\"` and contacts\naddressed as `tg:<chat_id>`.\n\n1. Create a bot with @BotFather, copy the token.\n2. On the laptop:\n\n```\nset OMNIFLOW_CP_URL=https://<your-control-plane>\nset OMNIFLOW_SERVICE_KEY=<same key the WhatsApp connector uses>\nset TELEGRAM_BOT_TOKEN=<token from BotFather>\npython3 telegram_bridge.py\n```\n\n3. In the portal, conversations from the bot appear like any other chat\n   (channel `telegram`, contact `tg:<chat_id>`). Broadcasts, sequences and\n   COD asks queued for a `tg:` contact are delivered by this bridge; the\n   WhatsApp bridge never sees them (command poll is channel-filtered).\n\nNotes:\n- Stdlib only (no pip installs).\n- Opted-out contacts (Compliance page / STOP keyword) never receive queued\n  sends - the Control Plane drops them at queue time.\n- Escalated chats, saved replies and the customer profile work unchanged\n  because the conversation store is channel-safe.\n");


